<?php
declare(strict_types=1);
require dirname(__DIR__).'/hackscan-private/core.php';
$passed=0;
function ok(bool $value,string $name): void { global $passed; if (!$value) throw new RuntimeException('FAIL: '.$name); $passed++; echo 'PASS: '.$name."\n"; }
function fails(callable $fn,string $name): void { try {$fn();}catch(Throwable){ok(true,$name);return;} ok(false,$name); }
function page(string $html='',array $headers=[],int $code=200): array {return ['code'=>$code,'location'=>null,'body'=>$html,'headers'=>array_merge(['content-type'=>['text/html; charset=utf-8']],$headers),'truncated'=>false,'tls'=>['fingerprint'=>'new-cert']];}
ok(hs_attrs("<meta name=\"\" content='' data-test=plain>") === ['name'=>'','content'=>'','data-test'=>'plain'], 'empty and unquoted HTML attributes parse without warnings');
$body='<!doctype html><html><head><title>Eksempel</title></head><body><p>En normal dansk hjemmeside.</p></body></html>';
$r=hs_analyze('example.dk','https://example.dk/',page($body)); hs_score($r);
ok(count(hs_controls())>=43,'every requested risk factor has an explicit catalog entry');
ok($r['controls']['php_eol']['confidence']==='none' && $r['controls']['cors']['confidence']==='none','unknown controls never display high confidence');
ok($r['controls']['webshell']['state']==='not_tested' && $r['controls']['config']['state']==='not_tested','internal checks and secret-file probes are never silently passed');
ok($r['controls']['malware']['state']==='not_tested','no malware claim without a signature engine');
ok($r['controls']['php_cve']['state']==='not_tested','PHP CVEs not guessed from unsupported fingerprints');
ok($r['controls']['hsts']['state']==='finding' && $r['controls']['csp']['state']==='finding','missing response protections create bounded risk factors');
ok($r['rating']['checked']<$r['rating']['total'] && $r['rating']['provisional'],'coverage and provisional character retained in the grade');
$failed=hs_analyze('example.dk','https://example.dk/',page('Forbidden',[],403));hs_score($failed);
ok($failed['rating']['score']===null && $failed['rating']['grade']===null,'blocked response never receives a clean A');
$none=hs_new_report('example.dk','https://example.dk/'); hs_score($none);
ok($none['rating']['checked']===0 && $none['rating']['score']===null,'unperformed assessment has zero coverage and no score');
$secret='DO_NOT_PERSIST_COOKIE_VALUE';
$rich='<html><head><title>Eksempel</title><meta name="generator" content="WordPress 6.1.0"><script src="https://cdn.example.com/jquery-3.4.1.min.js?token='.$secret.'"></script><script>window.location="https://other.dk/";</script></head><body><input value="'.$secret.'"><iframe src="https://other.dk/" width="0"></iframe></body></html>';
$r=hs_analyze('example.dk','https://example.dk/',page($rich,['x-powered-by'=>['PHP/7.4.33'],'server'=>['Apache/2.4.1'],'set-cookie'=>['session='.$secret.'; Path=/']]));
$db=hs_db(':memory:');
foreach ([60,58,28,6] as $code) {
    hs_network_report($db,'network.dk','https://network.dk/',new HSNetworkError('Test network failure',$code));
    $network=hs_report_get($db,'network.dk');
    ok(($network['controls']['tls']['state']==='finding')===in_array($code,[60,58],true),'network error '.$code.' handled without optional cURL constants');
    ok($network['rating']['score']===null,'network error '.$code.' remains ungraded');
}

$db->prepare('INSERT INTO intel(kind,payload,fetched_at) VALUES(?,?,?)')->execute(['wordpress',json_encode(['version'=>'6.8.3']),time()]);
$db->prepare('INSERT INTO intel(kind,payload,fetched_at) VALUES(?,?,?)')->execute(['kev',json_encode(['cves'=>['CVE-2020-11022']]),time()]);
hs_apply_intel($r,$db);hs_score($r);
ok($r['controls']['php_eol']['state']==='finding' && $r['controls']['php_eol']['confidence']==='low','unsupported PHP header treated as low-confidence risk, not confirmed vulnerability');
ok($r['controls']['wordpress']['state']==='finding','WordPress generator compared to fresh official-version cache');
ok($r['controls']['js_cve']['state']==='finding' && in_array('CVE-2020-11022',$r['cves'],true),'bounded documented JavaScript version interval produces a potential CVE match');
ok($r['controls']['kev']['state']==='finding','KEV match requires a concrete CVE candidate, not a product name alone');
ok($r['controls']['script_redirect']['state']==='finding','literal inline external JS redirect detected without execution');
ok($r['controls']['iframes']['state']==='finding','explicitly hidden external iframe is a low-confidence indicator');
ok($r['controls']['cookies']['state']==='finding' && !str_contains(json_encode($r),$secret),'cookie values, form values and resource query tokens are not stored');
ok($r['controls']['phishing']['state']!=='finding','a normal page is not labelled phishing');
$article=hs_analyze('example.dk','https://example.dk/',page('<html><body><p>Tutorial: window.location="https://other.dk/";</p></body></html>'));
ok($article['controls']['script_redirect']['state']!=='finding','JavaScript-looking article text outside script tags is not a redirect finding');
$canonical=hs_analyze('example.dk','https://www.example.dk/',page($body));
ok($canonical['controls']['redirect']['state']==='observed','www normalization never creates a compromise finding');
$external=hs_analyze('example.dk','https://other.dk/',page($body));hs_score($canonical);hs_score($external);
ok($external['controls']['redirect']['state']==='observed' && $canonical['rating']['score']===$external['rating']['score'],'a normal cross-domain redirect alone does not change security score');
$wildcard=hs_analyze('example.dk','https://example.dk/',page($body,['content-security-policy'=>["frame-ancestors *"]]));
ok($wildcard['controls']['frames']['state']==='finding','unrestricted frame-ancestors is not clickjacking protection');
$protected=hs_analyze('example.dk','https://example.dk/',page($body,['content-security-policy'=>["default-src 'self'; frame-ancestors 'none'"],'strict-transport-security'=>['max-age=31536000'],'set-cookie'=>['sid='.$secret.'; Secure; HttpOnly; SameSite=Lax']]));
ok($protected['controls']['frames']['state']==='pass' && $protected['controls']['cookies']['state']==='pass','recognized enforced frame policy and cookie attributes pass their bounded checks');
$cors=hs_analyze('example.dk','https://example.dk/',page($body,['access-control-allow-origin'=>['*'],'access-control-allow-credentials'=>['true']]));
ok($cors['controls']['cors']['state']==='observed','browser-rejected wildcard credential CORS is not claimed exploitable');
$normal=hs_analyze('example.dk','https://example.dk/',page('<html><script>eval(atob("bGVnaXRpbWF0ZQ=="));</script></html>'));
ok($normal['controls']['malware']['state']==='not_tested','eval and base64 alone are not malware evidence');
$root=['ok'=>true,'records'=>[['type'=>'TXT','txt'=>'v=spf1 -all'],['type'=>'A','ip'=>'1.1.1.1']]];
$dmarc=['ok'=>true,'records'=>[['type'=>'TXT','txt'=>'v=DMARC1; p=reject;']]];
hs_dns_report($protected,$root,$dmarc);
ok($protected['controls']['spf']['state']==='observed' && $protected['controls']['dmarc_policy']['state']==='observed','SPF and rejecting DMARC record observed without full-policy claims');
$policy=$protected; hs_dns_report($policy,$root,['ok'=>true,'records'=>[['type'=>'TXT','txt'=>'v=DMARC1; p=none;']]]);
ok($policy['controls']['dmarc_policy']['state']==='finding','monitor-only DMARC is a contextual risk factor');
$failure=$normal; hs_dns_report($failure,['ok'=>false,'records'=>[]],['ok'=>false,'records'=>[]]);
ok($failure['controls']['spf']['state']==='unknown' && $failure['controls']['dmarc']['state']==='unknown','DNS errors are not interpreted as absent SPF or DMARC');
$alias=$normal; hs_dns_report($alias,$root,['ok'=>true,'records'=>[['type'=>'CNAME','target'=>'provider.example']]]);
ok($alias['controls']['dmarc']['state']==='unknown','unfollowed DMARC aliases do not create missing-policy claims');
$changed=$protected; $changed['previous']=['text_hash'=>'old','addresses'=>['8.8.8.8'],'certificate'=>['fingerprint'=>'old-cert']];hs_dns_report($changed,$root,$dmarc);
ok($changed['controls']['content_change']['state']==='observed' && $changed['controls']['dns_change']['state']==='observed' && $changed['controls']['cert_change']['state']==='observed','content/DNS/certificate differences are observations rather than proof of compromise');
// The actual scanner persists HTTP codes and ignores canonical www hops.
$db=hs_db(':memory:'); hs_set($db,'running','1');hs_set($db,'phase','scan');
$db->exec("INSERT INTO results(domain,current_url,status) VALUES('example.dk','https://example.dk/','pending')");
hs_tick($db,fn()=>['code'=>301,'location'=>'https://www.example.dk/','body'=>'','truncated'=>false]);
ok((int)$db->query('SELECT COUNT(*) FROM redirect_hops WHERE external=1')->fetchColumn()===0,'www hop is never classified as external');
hs_tick($db,fn()=>['code'=>301,'location'=>'https://other.dk/','body'=>'','truncated'=>false]);
hs_tick($db,fn()=>['code'=>504,'location'=>null,'body'=>'','truncated'=>false]);
$g=hs_groups($db,'');
ok($g['review']['rows'][0]['redirect_code']===301 && $g['errors']['rows'][0]['http_code']===504,'external redirect and final HTTP error are independently stored in their own code fields');
// Multi-user migration, privilege enforcement and revocation.
$db=hs_db(':memory:'); $hash=password_hash('private fixture password',PASSWORD_DEFAULT);hs_set($db,'password_hash',$hash);hs_users_schema($db);$admin=hs_user_by_name($db,'admin');
ok($admin && password_verify('private fixture password',$admin['password_hash']),'legacy password migrates to admin without reset');
$id=hs_user_create($db,$admin,'reader','reader fixture password','viewer');$reader=hs_user_by_name($db,'reader');
ok($reader['password_hash']!=='reader fixture password' && $reader['role']==='viewer','additional user password is hashed and role stored');
fails(fn()=>hs_user_create($db,$reader,'hacker','another fixture password','admin'),'non-admin cannot create users even when bypassing UI');
fails(fn()=>hs_user_create($db,$admin,'READER','another fixture password','user'),'usernames are case-insensitively unique');
fails(fn()=>hs_user_create($db,$admin,'<script>','another fixture password','user'),'unsafe username rejected');
fails(fn()=>hs_user_create($db,$admin,'short','short','user'),'short new-user password rejected');
fails(fn()=>hs_user_update($db,$admin,(int)$admin['id'],'viewer',true),'administrator cannot downgrade their own account');
$session=['user_id'=>$reader['id'],'session_version'=>$reader['session_version'],'auth'=>time()];
ok(hs_current_user($db,$session)!==null,'active account session can authenticate');
hs_user_update($db,$admin,$id,'viewer',false);
ok(hs_current_user($db,$session)===null,'disabling an account revokes its existing sessions');
hs_user_update($db,$admin,$id,'user',true,'reset fixture password');
ok(password_verify('reset fixture password',hs_user_by_name($db,'reader')['password_hash']) && hs_current_user($db,$session)===null,'password reset changes hash and invalidates old sessions');
ok(!str_contains(json_encode($db->query('SELECT * FROM user_audit')->fetchAll()),'fixture password'),'audit history never records passwords');
// CISA mirror fallback is a separate job, so a single FPM request stays bounded.
$db=hs_db(':memory:');
$report=hs_analyze('example.dk','https://example.dk/',page($rich)); hs_report_save($db,$report);
$db->exec("INSERT INTO security_jobs(job_key,kind) VALUES('intel:kev','kev')");
$feedCalls=0;
hs_security_job($db,function($url) use (&$feedCalls) { $feedCalls++; return page('',[],403); });
ok($feedCalls===1 && $db->query("SELECT kind FROM security_jobs")->fetchColumn()==='kev_mirror','primary KEV denial schedules official mirror on a separate step');
hs_security_job($db,function($url) use (&$feedCalls) { $feedCalls++; ok(str_starts_with($url,'https://raw.githubusercontent.com/cisagov/kev-data/'),'KEV fallback only reads official CISA repository'); return page(json_encode(['vulnerabilities'=>[['cveID'=>'CVE-2020-11022']]])); });
$intel=$db->query("SELECT * FROM intel WHERE kind='kev'")->fetch();
ok($intel['error']==='' && in_array('CVE-2020-11022',json_decode($intel['payload'],true)['cves'],true),'validated mirror clears previous denial and populates KEV cache');
$db->exec("INSERT INTO security_jobs(job_key,kind,domain) VALUES('dns:example.dk','dns','example.dk')");
hs_security_job($db,fn()=>throw new RuntimeException('No HTTP request during DNS stage'),fn($name)=>str_starts_with($name,'_dmarc.')?$dmarc:$root);
$stored=hs_report_get($db,'example.dk');
ok($stored['complete'] && $stored['controls']['kev']['state']==='finding' && $stored['rating']['score']!==null,'DNS finalization incorporates refreshed KEV data and persists a complete bounded report');
ok((int)$db->query('SELECT COUNT(*) FROM security_history')->fetchColumn()===1,'completed assessment stores a history summary');
$db=hs_db(':memory:');hs_security_record($db,'example.dk','https://example.dk/',page($rich),[]);
ok((int)$db->query('SELECT COUNT(*) FROM security_jobs')->fetchColumn()===3,'security queue separates two feed calls and DNS from the HTTP request');
hs_set($db,'running','1');hs_set($db,'phase','scan');
$sentinel=0;
hs_tick($db,function($url) use (&$sentinel) { $sentinel++; return page(json_encode(['vulnerabilities'=>[['cveID'=>'CVE-2020-11022']]])); });
ok($sentinel===1 && (int)$db->query('SELECT COUNT(*) FROM security_jobs')->fetchColumn()===2,'one scanner tick executes at most one metadata fetch');
hs_set($db,'password_hash','preserve-me');hs_users_schema($db);
$admin=hs_user_by_name($db,'admin');
$db->exec("INSERT INTO domains(domain) VALUES('catalog.dk')");
$db->exec("INSERT OR REPLACE INTO intel(kind,payload) VALUES('wordpress','{}')");
fails(fn()=>hs_clear_results($db,['id'=>999,'role'=>'user']),'ordinary scanner user cannot clear shared results');
ok(hs_get($db,'running')==='1','rejected deletion preserves active scan');
hs_clear_results($db,$admin);
ok(hs_get($db,'running')==='0' && hs_get($db,'checked')==='0','clear stops scan and resets progress');
ok(hs_get($db,'password_hash')==='preserve-me' && hs_user_by_name($db,'admin')!==null,'clear preserves login and account settings');
ok((int)$db->query('SELECT COUNT(*) FROM domains')->fetchColumn()===1 && (int)$db->query('SELECT COUNT(*) FROM intel')->fetchColumn()>0,'clear preserves discovery cache and security intelligence');
$sentinel=0;hs_tick($db,function($url) use (&$sentinel){$sentinel++;return page();});
ok($sentinel===0,'scheduled worker cannot repopulate results after clearing');
echo "\n$passed security and account checks passed.\n";
